{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "In healthy subjects, a 20 mg ziprasidone capsule had a mean absolute oral bioavailability of 60 ± 23% in the fed state, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Urapidil oral bioavailability is 78% and is reported not to depend on food intake, supporting high bioavailability under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Brexanolone has <5% oral bioavailability compared with intravenous infusion, providing the clearest contradictory evidence for the F ≥ 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Prediction is high: multiple high-transferability records report absolute oral bioavailability ≥52%, including fed-state and food-independent data; the only clear sub-threshold value (<5%) has lower transferability and no fed-state match.",
  "evidence_gaps": [
    "Molecule 6 (mCPP) has a wide absolute bioavailability range (12–84%) that straddles the 20% threshold, so its direction is uncertain.",
    "Molecule 5 (TFMPP) provides only qualitative 'low' bioavailability without a numeric value, so it is not threshold-decisive.",
    "Several positive records (trazodone, eltrombopag, ondansetron) were obtained under fasted or unspecified conditions, so their fed-state transferability is less direct."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

